// Marketing-site copy dictionary. RU is the default locale (parity with the
// reference cloud-provider landing); EN mirrors it for the language toggle.
// Console UI strings are intentionally NOT here — this is marketing only.

export type Locale = "ru" | "en";

export const LOCALES: Locale[] = ["ru", "en"];
export const DEFAULT_LOCALE: Locale = "ru";

type Feature = { title: string; desc: string };
type Faq = { q: string; a: string };
type AltPage = {
  heroTitle: string;
  heroSubtitle: string;
  featuresTitle: string;
  features: Feature[];
  faqTitle: string;
  faq: Faq[];
  howtoTitle?: string;
  howtoSubtitle?: string;
  howtoSteps?: Step[];
  mappingTitle?: string;
  mappingSubtitle?: string;
  mapping?: MappingRow[];
  mappingHeaders?: [string, string, string];
  notPortableTitle?: string;
  notPortableSubtitle?: string;
  notPortable?: Feature[];
  payNote?: { title: string; body: string; linkLabel: string; linkHref: string };
};
type Plan = {
  key: string;
  name: string;
  price: string;
  period: string;
  tagline: string;
  features: string[];
  quotaMatrix: {
    apps: string;
    databases: string;
    storage: string;
    domains: string;
    environments: string;
    members: string;
    backups: string;
    support: string;
  };
  cta: string;
  highlight?: boolean;
};
type Step = { num: string; title: string; desc: string };
type Scenario = { tag: string; title: string; desc: string };
type PricingTeaser = { name: string; price: string; tagline: string; bullets: string[]; highlight?: boolean };
type MappingRow = { from: string; to: string; note: string };
type StatusService = { id: string; name: string };
type StatusRadar = {
  heroTitle: string;
  heroSubtitle: string;
  vantageLabel: string;
  updatedLabel: string;
  loadingText: string;
  errorText: string;
  reachableLabel: string;
  unreachableLabel: string;
  unknownLabel: string;
  tableHeaders: {
    service: string;
    availability: string;
    httpStatus: string;
    latency: string;
    tls: string;
  };
  services: StatusService[];
  disclaimerTitle: string;
  disclaimer: string;
  paymentTitle: string;
  paymentText: string;
  ctaPrimaryLabel: string;
  ctaSecondaryLabel: string;
  ctaTitle: string;
  ctaSubtitle: string;
  faqTitle: string;
  faq: Faq[];
  datasetName: string;
  datasetDescription: string;
};
type UploadDeployPage = {
  heroTitle: string;
  heroSubtitle: string;
  stepsTitle: string;
  stepsSubtitle: string;
  steps: Step[];
  featuresTitle: string;
  features: Feature[];
  faqTitle: string;
  faq: Faq[];
  mappingTitle?: string;
  mappingSubtitle?: string;
  mapping?: MappingRow[];
  notPortableTitle?: string;
  notPortableSubtitle?: string;
  notPortable?: Feature[];
};
type MigrateGuide = {
  heroTitle: string;
  heroSubtitle: string;
  stepsTitle: string;
  stepsSubtitle: string;
  steps: Step[];
  mappingTitle: string;
  mappingSubtitle: string;
  mapping: MappingRow[];
  notesTitle: string;
  notes: Feature[];
  faqTitle: string;
  faq: Faq[];
  ctaTitle: string;
  ctaSubtitle: string;
  ctaButton: string;
};

