    faqTitle: "Хостинг FastAPI - частые вопросы",
    faq: [
      { q: "Куда задеплоить FastAPI, если я не умею настраивать сервер?", a: "В Dada Cloud: подключаете репозиторий, платформа сама определяет FastAPI, собирает и запускает приложение. Сервер, nginx и сертификаты настраивать не нужно." },
      { q: "Нужен ли Dockerfile?", a: "Нет. Достаточно requirements.txt или pyproject.toml с fastapi - платформа соберёт приложение сама. Если Dockerfile всё же есть, он будет использован." },
      { q: "На каком порту должно работать приложение?", a: "Приложение должно слушать 0.0.0.0 и порт из переменной окружения PORT, которую передаёт платформа. Если порт задан в uvicorn.run в коде, платформа его вычитает сама, по умолчанию - 8000." },
      { q: "Как подключить базу данных?", a: "Создаёте managed PostgreSQL рядом с приложением - DATABASE_URL появится в переменных окружения автоматически, руками собирать строку подключения не нужно." },
      { q: "Есть бесплатный хостинг для FastAPI?", a: "Да, первое приложение с PostgreSQL и доменом можно держать на бесплатном тарифе без привязки карты." },
      { q: "Что делать с автодокументацией /docs и /redoc?", a: "Ничего дополнительно. FastAPI отдаёт /docs и /redoc сам, а платформа проксирует все пути приложения — Swagger UI открывается по выданному HTTPS-адресу сразу после деплоя. Если документацию нужно закрыть от посторонних, отключайте её в самом приложении параметром docs_url=None." },
      { q: "Как запускать миграции Alembic?", a: "Так же, как привыкли: командой alembic upgrade head при старте процесса или вручную. Платформа не вмешивается в команду запуска приложения, поэтому цепочка вида alembic upgrade head && uvicorn app:app работает без правок." },
      { q: "Приложение деплоится из GitHub или можно без git?", a: "Оба варианта. Подключаете GitHub-репозиторий — каждый пуш собирает новую версию. Либо загружаете zip-архив с проектом прямо в консоли, если с git разбираться не хочется." },
      { q: "Что с фоновыми задачами и воркерами?", a: "Фоновый процесс (Celery, arq, свой цикл) создаётся как отдельное приложение в режиме «фоновый воркер» — публичный домен ему не выдаётся. API и воркер живут рядом в одном проекте и видят одну и ту же базу." },
    ],
