    faqTitle: "Деплой без git - частые вопросы",
    faq: [
      { q: "Нужен ли git или GitHub, чтобы задеплоить проект?", a: "Нет. Заархивируйте проект в zip или tar.gz и загрузите архив в консоли - платформа соберёт и запустит приложение без репозитория." },
      { q: "Какие форматы архива и какой лимит размера?", a: "Zip или tar.gz, до 100MB." },
      { q: "Как платформа определяет фреймворк?", a: "Ищет Dockerfile (и порт в EXPOSE), package.json с next, vite или react-scripts, или requirements.txt и pyproject.toml с fastapi, flask, django или streamlit." },
      { q: "На каком порту должно слушать приложение?", a: "0.0.0.0 и порт из переменной окружения PORT. Если в архиве есть Dockerfile с EXPOSE, платформа возьмёт порт оттуда." },
      { q: "Можно загрузить экспорт из Lovable, Bolt или v0?", a: "Да - заархивируйте папку экспорта в zip и загрузите как обычный проект." },
      { q: "Что если мой фреймворк не распознаётся автоматически?", a: "Добавьте в архив Dockerfile с EXPOSE нужного порта - платформа соберёт приложение по нему." },
      { q: "Нужно ли сначала создавать приложение в консоли?", a: "Да - сначала создаётся приложение с именем, а затем в него загружается архив с кодом. Это два быстрых шага на одной странице." },
      { q: "Это бесплатно?", a: "Да, первое приложение можно держать на бесплатном тарифе без привязки карты." },
      { q: "Как обновить приложение после правок?", a: "Заархивируйте папку заново и загрузите архив ещё раз - запустится новая сборка, а старая версия проработает до момента переключения. Никакого git и коммитов." },
      { q: "Что положить в архив: папку или её содержимое?", a: "Достаточно заархивировать папку проекта целиком - платформа сама найдёт корень по манифесту внутри. Виртуальное окружение (venv), node_modules и .git можно не класть: они только раздувают архив и не нужны для сборки." },
      { q: "Куда девать секреты и ключи API?", a: "В переменные окружения приложения - они задаются в консоли и попадают в процесс при старте. Файлы .env в архиве использовать не стоит: секреты попадут в образ и в логи сборки." },
      { q: "Можно потом переключиться на git?", a: "Да. Подключите GitHub-репозиторий к тому же приложению - дальше сборки пойдут по пушу, а адрес и переменные окружения останутся прежними." },
      { q: "Экспорт из Lovable, Bolt или v0 подойдёт?", a: "Да, это обычная папка с package.json. Заархивируйте её и загрузите - Next.js, Vite или React определятся автоматически и соберутся без настройки." },
      { q: "Почему архив не приняли?", a: "Три частые причины: размер больше 100MB, формат не zip и не tar.gz, или внутри нет ни Dockerfile, ни package.json, ни requirements.txt - платформе не по чему определить, как собирать проект." },
    ],
